WITH with_windows AS (SELECT id, opened_date, sqft, COUNT(sqft) OVER w_ordered AS last7_count_sqft, AVG(sqft) OVER w_ordered AS last7_avg_sqft, SUM(sqft) OVER w_ordered AS last7_sum_sqft, AVG(sqft) OVER (PARTITION BY region ORDER BY opened_date, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS sqft_avg_6 FROM stores WINDOW w_ordered AS (PARTITION BY region, city ORDER BY sqft, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)) SELECT id, opened_date, sqft, last7_count_sqft, last7_avg_sqft, last7_sum_sqft, sqft_avg_6 FROM with_windows ORDER BY last7_sum_sqft DESC NULLS FIRST, sqft_avg_6
